def comp(i):
    # connected component of 1s (4-connectivity) in input, largest
    H,W=len(i),len(i[0])
    seen=[[False]*W for _ in range(H)]; best=[]; bestc=-1
    import collections
    for r in range(H):
        for c in range(W):
            if i[r][c]==1 and not seen[r][c]:
                q=collections.deque([(r,c)]); seen[r][c]=True; cells=[(r,c)]
                while q:
                    a,b=q.popleft()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and i[na][nb]==1 and not seen[na][nb]:
                            seen[na][nb]=True; q.append((na,nb)); cells.append((na,nb))
                if len(cells)>bestc: bestc=len(cells); best=cells
    return best
