    for r in range(h):
        for c in range(w):
            if bg[r][c]!=1 and not vis[r][c]:
                q=[(r,c)]; vis[r][c]=True; cells=[(r,c)]
                while q:
                    a,b=q.pop()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
